document.addEventListener('DOMContentLoaded', () => { function spawnBalloon() { const isMobile = window.innerWidth < 768; if(isMobile && document.getElementsByClassName('balloon-anim').length > 5) return; const balloon = document.createElement('div'); balloon.classList.add('balloon-anim'); const colors = [ '#FF9EAA', '#89CFF0', '#FFD54F', '#81C784', '#BA68C8', '#FF8A65', '#4DD0E1', '#FFD180' ]; const randomColor = colors[Math.floor(Math.random() * colors.length)]; const size = Math.floor(Math.random() * 30) + 40; const left = Math.floor(Math.random() * 100); balloon.style.background = randomColor; balloon.style.width = `${size}px`; balloon.style.height = `${size * 1.2}px`; balloon.style.left = `${left}%`; balloon.style.bottom = '-100px'; document.body.appendChild(balloon); setTimeout(() => { balloon.remove(); }, 10000); } setInterval(spawnBalloon, 300); const scrollToTopBtn = document.getElementById("scrollToTopBtn"); window.onscroll = function() { scrollFunction(); }; function scrollFunction() { if (document.body.scrollTop > 300 || document.documentElement.scrollTop > 300) { scrollToTopBtn.style.display = "block"; } else { scrollToTopBtn.style.display = "none"; } } scrollToTopBtn.addEventListener('click', () => { window.scrollTo({top: 0, behavior: 'smooth'}); }); const packageSelect = document.getElementById('package-select'); const extraKidsInput = document.getElementById('extra-kids'); const addons = document.querySelectorAll('.calc-addon'); const totalDisplay = document.getElementById('calc-total'); function calculateTotal() { let total = 0; if(packageSelect) { total += parseInt(packageSelect.value); } if(extraKidsInput) { const kidsCount = Math.max(0, parseInt(extraKidsInput.value) || 0); total += kidsCount * 10; } addons.forEach(addon => { if(addon.checked) { total += parseInt(addon.value); } }); if(totalDisplay) { animateValue(totalDisplay, parseInt(totalDisplay.innerText), total, 500); } } if(packageSelect) packageSelect.addEventListener('change', calculateTotal); if(extraKidsInput) extraKidsInput.addEventListener('input', calculateTotal); addons.forEach(addon => addon.addEventListener('change', calculateTotal)); function animateValue(obj, start, end, duration) { let startTimestamp = null; const step = (timestamp) => { if (!startTimestamp) startTimestamp = timestamp; const progress = Math.min((timestamp - startTimestamp) / duration, 1); obj.innerHTML = Math.floor(progress * (end - start) + start); if (progress < 1) { window.requestAnimationFrame(step); } else { obj.innerHTML = end; } }; window.requestAnimationFrame(step); } const cookieBanner = document.getElementById('cookieBanner'); const acceptBtn = document.getElementById('acceptCookies'); if (!localStorage.getItem('cookiesAccepted')) { setTimeout(() => { cookieBanner.classList.add('show'); }, 1000); } if(acceptBtn) { acceptBtn.addEventListener('click', () => { localStorage.setItem('cookiesAccepted', 'true'); cookieBanner.classList.remove('show'); }); } const revealElements = document.querySelectorAll("h2, .package-card, .service-item, .testimonial-card, .hero-content, .about-content, .rules-list"); const revealObserver = new IntersectionObserver((entries, observer) => { entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('active'); observer.unobserve(entry.target); } }); }, { root: null, threshold: 0.1, rootMargin: "0px 0px -50px 0px" }); revealElements.forEach(el => { el.classList.add('reveal'); revealObserver.observe(el); }); const lightbox = document.getElementById('lightbox'); const lightboxImg = document.getElementById('lightbox-img'); const lightboxCaption = document.getElementById('lightbox-caption'); const closeBtn = document.querySelector('.lightbox-close'); if (lightbox) { const allImages = document.querySelectorAll('.gallery-item-scroll img, .gallery-item img'); allImages.forEach(img => { img.style.pointerEvents = "auto"; img.style.cursor = "zoom-in"; img.addEventListener('click', () => { lightbox.classList.add('active'); lightboxImg.src = img.src; lightboxCaption.textContent = img.alt; document.body.style.overflow = 'hidden'; }); }); function closeLightbox() { lightbox.classList.remove('active'); document.body.style.overflow = 'auto'; } if (closeBtn) closeBtn.addEventListener('click', closeLightbox); lightbox.addEventListener('click', (e) => { if (e.target === lightbox) { closeLightbox(); } }); } });